{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "DAPPD, a 2,6-diaminopurine nucleoside with the highest Morgan similarity to the query, was detected in plasma, CSF, and brain after intraperitoneal and oral administration in mice, directly demonstrating meaningful CNS access for this purine-nucleoside scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cladribine, a halogenated purine nucleoside, reaches CSF concentrations approximately 25% of plasma in humans, showing that purine nucleosides with high polar surface area can still achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Nelarabine, a purine nucleoside analogue, showed excellent CSF penetration in non-human primate pharmacokinetic studies, supporting transferable CNS access for the purine nucleoside family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Fludarabine brain uptake in mice was transporter-mediated and reduced by an ENT1 inhibitor, indicating that purine nucleoside analogues can cross the BBB via nucleoside transporters despite polar character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Guanosine entered the CNS within minutes after systemic administration and showed dose-dependent CSF increases after oral dosing, attributed to nucleoside transporters at the BBB; the query is a guanosine-like carbocyclic purine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "DDA, a dideoxypurine nucleoside, had a brain uptake index <2%, showing that some purine nucleosides lack measurable BBB transport; this is a minority observation among the direct nucleoside measurements and is outweighed by the positive analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: the query is abacavir, a carbocyclic purine nucleoside; multiple direct in vivo measurements in closely related purine nucleosides (DAPPD, cladribine, nelarabine, fludarabine, guanosine) demonstrate meaningful CSF/brain exposure, often via nucleoside transporters, overriding the uncertain low-passive-diffusion prior.",
  "evidence_gaps": [
    "No direct abacavir CSF/brain measurement is present in the evidence set; the closest analogues have Morgan similarities below 0.4.",
    "The relative contributions of passive diffusion, nucleoside transporters, and efflux transporters to abacavir CNS entry are not directly quantified in the supplied records.",
    "Contradictory poor-uptake results for DDA and adenosine-receptor agonists indicate that transporter recognition is structure-specific."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

